// Validate agent input. No defaults for specs; missing spec stays missing (agent outputs 'unavailable').
const i = $input.first().json;
for (const f of ['procurement_id','requirement','currency']) if (!i[f]) throw new Error('Missing required field: ' + f);
if (!/^[A-Z]{3}$/.test(i.currency)) throw new Error('currency must be ISO 4217');
return [{ json: { procurement_id: i.procurement_id, trace_id: i.trace_id, requirement: i.requirement, quantity: i.quantity ?? null, budget: i.budget ?? null, currency: i.currency, delivery_requirement: i.delivery_requirement ?? null, mandatory_specs: i.mandatory_specs ?? {}, preferred_specs: i.preferred_specs ?? {} } }];

