// Enforce output schema + no-fake rules: reject products without source_url, reject Amazon/Flipkart.
const out = $input.first().json?.output ?? $input.first().json;
const pid = $('Validate Input').first().json.procurement_id;
const products = Array.isArray(out.products) ? out.products : [];
for (const p of products) {
  if (!p.source_url) throw new Error('Rejecting product without source_url: ' + (p.product_id ?? '?'));
  const clean = String(p.source_url || '').trim().replace(/ /g, '%20');
  const hm = /^https?:\/\/([^\/\s?#]+)/i.exec(clean);
  if (!hm || !hm[1] || clean.length > 2048) throw new Error('Invalid source_url: ' + p.source_url);
  if (/(^|.)amazon\.|(^|.)flipkart\./i.test(hm[1].toLowerCase())) throw new Error('Excluded source in Phase 1: ' + p.source_url);
  p.source_url = clean;
  if (!p.product_id || !p.name || !p.specifications || !p.source || !p.retrieved_at) throw new Error('Product missing required field: ' + JSON.stringify(p).slice(0, 200));
}
const live = products.filter((p) => p.data_status === 'LIVE').length;
return [{ json: { procurement_id: pid, products: products.map((p) => ({ brand: 'unavailable', ...p })), data_status: products.length === 0 ? 'UNAVAILABLE' : live === products.length ? 'LIVE' : 'PARTIAL', unavailable_reasons: products.length === 0 ? ['No verifiable products from configured providers'] : [] } }];

// Deterministic gateway query (no LLM): requirement text plus human-readable
// spec values (never raw key names like ram_gb_min, which poison provider queries).
const i = $('Validate Input').first().json;
const parts = [i.requirement, 'buy'];
for (const [k, v] of Object.entries(i.mandatory_specs || {})) {
  if (typeof v !== 'number') continue;
  const kl = String(k).toLowerCase();
  if (kl.includes('ram') || kl.includes('memory')) parts.push(v + 'GB RAM');
  else if (kl.includes('stor') || kl.includes('ssd') || kl.includes('disk')) parts.push(v + 'GB SSD');
}
const query = parts.filter(Boolean).join(' ').slice(0, 300);
return [{ json: { tool: 'product-search', query, max_results: 10 } }];

// Deterministic normalization (no LLM): verified envelopes -> product candidates.
// Suitability is NOT judged here: everything stays PARTIAL for later review.
// No URL -> rejected. Amazon/Flipkart -> rejected. Missing fields -> unavailable.
const items = $input.all().map((i) => i.json);
const seen = new Set();
const products = [];
const procShort = String(($('Validate Input').first().json.procurement_id) || '').replace(/-/g, '').slice(0, 8);
for (const e of items) {
  if (!e || e.data_status === 'UNAVAILABLE' || !e.source_url) continue;
  if (/amazon\.|flipkart\./i.test(e.source_url)) continue;
  const key = e.source + ':' + e.source_url;
  if (seen.has(key)) continue;
  seen.add(key);
  const d = e.data || {};
  const slug = String(d.product_name || d.title || 'product').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 40) || 'product';
  products.push({
    product_id: 'p-' + slug.slice(0, 30) + '-' + procShort + '-' + seen.size,
    name: String(d.product_name || d.title || 'unavailable').slice(0, 300),
    brand: 'unavailable',
    specifications: {},
    source: e.source,
    source_url: e.source_url,
    retrieved_at: e.retrieved_at,
    data_status: 'PARTIAL',
    confidence: (typeof e.confidence === 'number' ? e.confidence : 0.5),
    raw: { serpapi_product_id: d.serpapi_product_id ?? null, title: d.product_name ?? d.title ?? null },
  });
}
const inp = $('Validate Input').first().json;
return [{ json: { procurement_id: inp.procurement_id, products, data_status: products.length ? 'PARTIAL' : 'UNAVAILABLE', unavailable_reasons: products.length ? [] : ['No verifiable results from configured providers'] } }];
